S = "Hakeem Force Academy"
QS = [
(S, "In which continent is Moscow, the capital of Russia, located?", ["Asia", "Europe", "North America", "Africa"], 1,
 "Moscow lies on the Moskva River in the western part of Russia, which is in the European part of the country. So it is counted as a European city.", "Moscow is the largest city entirely in Europe by population.", [2014, 3547]),
(S, "The Minto-Morley Reforms of 1909 were related to which country?", ["India", "Egypt", "Ireland", "Turkey"], 0,
 "These reforms were the Indian Councils Act 1909, passed by the British government for British India. They gave Muslims separate electorates.", "Lord Minto was the Viceroy and John Morley was the Secretary of State for India.", [3724]),
(S, "Who is called Shaheed-e-Millat in Pakistan?", ["Liaquat Ali Khan", "Fatima Jinnah", "Allama Iqbal", "Chaudhry Rahmat Ali"], 0,
 "Liaquat Ali Khan, the first Prime Minister of Pakistan, was assassinated in Rawalpindi in 1951. He is therefore called Shaheed-e-Millat, the martyr of the nation.", "Liaquat Ali Khan was shot at Company Bagh, which was later renamed Liaquat Bagh.", [614]),
(S, "What is the minimum number of ayat (verses) in a surah of the Quran?", ["3", "5", "7", "10"], 0,
 "The shortest surahs, Al-Asr, Al-Kawthar and An-Nasr, each have 3 ayat. No surah has fewer.", "Surah Al-Baqarah is the longest surah with 286 ayat.", [3030]),
(S, "Who is the current Foreign Minister of Pakistan (2026)?", ["Shah Mahmood Qureshi", "Bilawal Bhutto Zardari", "Mohammad Ishaq Dar", "Khawaja Asif"], 2,
 "Mohammad Ishaq Dar serves as Deputy Prime Minister and Foreign Minister of Pakistan. He was still in office in August 2026 according to the Ministry of Foreign Affairs.", "Bilawal Bhutto Zardari was Foreign Minister from 2022 to 2023 before Ishaq Dar took the post in 2024.", [4215]),
(S, "Who was the first Finance Minister of Pakistan?", ["Malik Ghulam Muhammad", "Chaudhry Muhammad Ali", "Mohammad Ali Bogra", "Zafarullah Khan"], 0,
 "Malik Ghulam Muhammad was Finance Minister in the first cabinet of Liaquat Ali Khan in 1947. He later became the third Governor General.", "He presented the first budget of Pakistan in 1948.", [4355]),
(S, "What is the commonly quoted range of Pakistan's Babur (Hatf-VII) cruise missile?", ["350 km", "700 km", "1500 km", "2500 km"], 1,
 "The Babur ground-launched cruise missile, first tested in 2005, is commonly given a range of about 700 km. Newer versions are reported with different ranges.", "Sources differ because later versions such as Babur-1B and Babur-3 have other stated ranges.", [1005]),
(S, "In which year did Pakistan launch its first rocket into space, the Rehbar-1?", ["1962", "1971", "1990", "1998"], 0,
 "Rehbar-1 was launched from Sonmiani in Balochistan on 7 June 1962 by SUPARCO. It made Pakistan the third country in Asia and the tenth in the world to launch a rocket into space.", "SUPARCO was established in 1961.", [3408]),
(S, "Find the missing number in the series: 66, 63, 56, 45, ?", ["21", "28", "30", "35"], 2,
 "The differences are minus 3, minus 7, minus 11, so the next difference is minus 15. Then 45 minus 15 equals 30.", "The differences themselves fall by 4 each time.", [3866]),
(S, "What is the antonym of modesty?", ["Humility", "Arrogance", "Shyness", "Simplicity"], 1,
 "Modesty means not showing off or thinking too highly of oneself. The opposite is arrogance, which is excessive pride.", "Vanity is another word opposite to modesty.", [927]),
(S, "What is the synonym of modesty?", ["Pride", "Boldness", "Humility", "Greed"], 2,
 "Modesty means a humble and unassuming attitude. Humility has the same meaning.", "Modesty can also mean decent behaviour in dress.", [3187]),
(S, "Who are called Ummul-Momineen (Mothers of the Believers)?", ["Daughters of the Prophet (PBUH)", "Wives of the Prophet (PBUH)", "Mothers of the Caliphs", "Female companions who fought in battles"], 1,
 "The Quran calls the wives of the Holy Prophet (PBUH) the mothers of the believers. This is a title of respect.", "Hazrat Khadija (RA) was the first of the Ummul-Momineen.", [4094]),
(S, "If the 1st day of a month is Monday, which day will the 16th be?", ["Monday", "Tuesday", "Wednesday", "Sunday"], 1,
 "From the 1st to the 16th is 15 days. 15 divided by 7 leaves remainder 1, so the day is one day after Monday, which is Tuesday.", "The 8th and 15th of that month would also be Mondays.", [1885]),
(S, "Which two cities does the M-2 motorway connect?", ["Lahore and Islamabad", "Islamabad and Peshawar", "Karachi and Hyderabad", "Lahore and Multan"], 0,
 "The M-2 is the Lahore-Islamabad Motorway, about 367 km long. It opened in 1997.", "It is also known as the Salt Range Motorway because it passes through the Salt Range.", [3652]),
(S, "Which mountain range lies along the Sindh side of Pakistan, on the border with Balochistan?", ["Kirthar Range", "Karakoram Range", "Safed Koh", "Salt Range"], 0,
 "The Kirthar Range runs north to south along the Sindh and Balochistan border. Its highest point is Zardak Peak.", "The Kirthar Range is the southern extension of the Sulaiman Range.", [988]),
(S, "A train is moving at 45 km per hour. How far will it travel in 5 minutes?", ["3.75 km", "4.5 km", "2.25 km", "5 km"], 0,
 "5 minutes is 5/60 = 1/12 hour. Distance = 45 x 1/12 = 3.75 km.", "Speed in km/h divided by 60 gives the distance covered in one minute.", [1337]),
(S, "What is 0.01 multiplied by 100?", ["0.1", "10", "1", "0.001"], 2,
 "Multiplying by 100 moves the decimal point two places to the right. So 0.01 x 100 = 1.", "Multiplying by 10 moves the decimal point one place right.", [2608]),
(S, "According to the BODMAS rule, which of these operations is solved first?", ["Addition", "Subtraction", "Multiplication", "None of these"], 2,
 "BODMAS means Brackets, Orders, Division, Multiplication, Addition, Subtraction. Among the given options, multiplication comes before addition and subtraction.", "Brackets are always solved first of all.", [3915]),
(S, "Find the odd one out: Delhi, Ahmedabad, Mumbai, Sibbi.", ["Delhi", "Ahmedabad", "Mumbai", "Sibbi"], 3,
 "Delhi, Ahmedabad and Mumbai are cities of India. Sibbi (Sibi) is a city of Balochistan, Pakistan.", "Sibi is famous for its annual Sibi Mela and its very hot summers.", [3911]),
(S, "In which city is Bait-ul-Muqaddas (Al-Aqsa Mosque) located?", ["Jerusalem", "Makkah", "Damascus", "Cairo"], 0,
 "Bait-ul-Muqaddas is in Jerusalem, in Palestine. It was the first qibla of the Muslims.", "The qibla was changed to the Kaaba in the second year of Hijra.", [563]),
(S, "What was the name of the brother of Hazrat Musa (AS)?", ["Hazrat Haroon (AS)", "Hazrat Yaqoob (AS)", "Hazrat Yusuf (AS)", "Hazrat Ibrahim (AS)"], 0,
 "Hazrat Haroon (AS) was the elder brother of Hazrat Musa (AS). He was also a prophet and helped Musa (AS) before Pharaoh.", "Musa (AS) asked Allah to make Haroon (AS) his helper.", [990, 3137]),
(S, "Which holy book was revealed on Hazrat Musa (AS)?", ["Zabur", "Injeel", "Torah (Taurat)", "Quran"], 2,
 "The Torah (Taurat) was revealed to Hazrat Musa (AS) on Mount Tur.", "Zabur was revealed to Dawud (AS) and Injeel to Isa (AS).", [1121]),
(S, "Which country suffered the greatest number of deaths in World War II?", ["Germany", "Soviet Union", "United States", "Japan"], 1,
 "The Soviet Union lost about 27 million people, more than any other country. Most estimates agree on this.", "Poland lost the largest share of its population, about 17 percent.", [3722]),
(S, "On which sector is the economy of Pakistan traditionally said to depend mostly?", ["Tourism", "Mining", "Agriculture", "Shipping"], 2,
 "Pakistan is an agricultural country. Agriculture employs a large share of the workforce and supports exports like cotton and textiles.", "Sources differ, as the services sector now has the largest share of GDP.", [837]),
]
